class Solution {
public:
    bool makeStringsEqual(std::string s, std::string target) {
        bool s_has1 = s.find('1') != std::string::npos;
        bool t_has1 = target.find('1') != std::string::npos;
        return s_has1 == t_has1;
    }
};

class Solution {
    public boolean makeStringsEqual(String s, String target) {
        return s.contains("1") == target.contains("1");
    }
}

var makeStringsEqual = function(s, target) {
    return s.includes('1') === target.includes('1');
};
